from fastapi import FastAPI, HTTPException, Depends
from typing import List, Optional
from .models import Task, TaskCreate, TaskUpdate, Project, TaskStatus
from .database import tasks, projects
from .auth import require_api_key

app = FastAPI(title="Project Management API")


@app.get("/projects", response_model=List[Project])
async def list_projects():
    return projects


@app.get("/tasks", response_model=List[Task])
async def list_tasks(
    status: Optional[TaskStatus] = None,
    priority: Optional[int] = None,
    assigned_to: Optional[str] = None,
    page: int = 1,
    page_size: int = 20,
):
    filtered_tasks = tasks
    if status is not None:
        filtered_tasks = [t for t in filtered_tasks if t.status == status]
    if priority is not None:
        filtered_tasks = [t for t in filtered_tasks if t.priority == priority]
    if assigned_to is not None:
        filtered_tasks = [t for t in filtered_tasks if t.assigned_to == assigned_to]

    start_idx = (page - 1) * page_size
    end_idx = start_idx + page_size
    return filtered_tasks[start_idx:end_idx]


@app.get("/tasks/{task_id}", response_model=Task)
async def get_task(task_id: int):
    for task in tasks:
        if task.id == task_id:
            return task
    raise HTTPException(status_code=404, detail="Task not found")


@app.post("/tasks", response_model=Task, status_code=201)
async def create_task(
    task_in: TaskCreate,
    username: str = Depends(require_api_key),
):
    # Validate project exists
    project_exists = any(p.id == task_in.project_id for p in projects)
    if not project_exists:
        raise HTTPException(status_code=404, detail="Project not found")

    # Auto-generate a unique integer ID
    new_id = max(t.id for t in tasks) + 1 if tasks else 1

    new_task = Task(
        id=new_id,
        title=task_in.title,
        status=task_in.status,
        priority=task_in.priority,
        project_id=task_in.project_id,
        assigned_to=task_in.assigned_to,
    )
    tasks.append(new_task)
    return new_task


@app.put("/tasks/{task_id}", response_model=Task)
async def update_task(
    task_id: int,
    task_in: TaskUpdate,
    username: str = Depends(require_api_key),
):
    target_task = None
    for task in tasks:
        if task.id == task_id:
            target_task = task
            break
    if not target_task:
        raise HTTPException(status_code=404, detail="Task not found")

    update_data = task_in.model_dump(exclude_unset=True)
    if "title" in update_data:
        target_task.title = update_data["title"]
    if "status" in update_data:
        target_task.status = update_data["status"]
    if "priority" in update_data:
        target_task.priority = update_data["priority"]
    if "assigned_to" in update_data:
        target_task.assigned_to = update_data["assigned_to"]

    return target_task


@app.delete("/tasks/{task_id}", response_model=Task)
async def delete_task(
    task_id: int,
    username: str = Depends(require_api_key),
):
    for idx, task in enumerate(tasks):
        if task.id == task_id:
            return tasks.pop(idx)
    raise HTTPException(status_code=404, detail="Task not found")
